// create nano identity file WITHOUT leaking seed to stdout
import { writeFileSync, readFileSync, existsSync } from 'node:fs';
import nc from 'nanocurrency';
const file = 'wallet/keys/nano.json';
if (existsSync(file)) { console.log('nano.json already exists; keeping it. addr:', JSON.parse(readFileSync(file, 'utf8')).address); process.exit(0); }
const seed = await nc.generateSeed();
const sk = nc.deriveSecretKey(seed, 0);
const pub = nc.derivePublicKey(sk);
const addr = nc.deriveAddress(pub, 0, { useNanoPrefix: true });
const rep = 'nano_1xug1q5t7nxoj3ywwzokiea9jz8fq8qfgzp8pbyfr3co3e5xgj755uofu8ue'; // pursekeeper hot wallet as placeholder representative source? No - representative must be an account, standard default:
const stdRep = 'nano_3sw6s1we3jgkw9qtb99rdxrxjxj9d1ejge1immqsojd4sw3hme3jcw8yz1gb'; // nano default representative (nano.org) - will confirm before first block
writeFileSync(file, JSON.stringify({
  seed, sk, public_key: pub, address: nc.checkAddress(addr) ? addr : addr.replace(/^xrb_/, 'nano_'),
  representative_pending: stdRep,
  created: new Date().toISOString(),
  note: 'Receiving + agent-payment wallet for pursekeeper/Nano rail. Generated by OpenClaw (expeditious). Index 0.'
}, null, 2));
console.log('WROTE wallet/keys/nano.json; address:', addr);

// wrapper: run no-node.js with seed from wallet/keys/nano.json without printing it
import { readFileSync } from 'node:fs';
import { spawnSync } from 'node:child_process';
const k = JSON.parse(readFileSync('wallet/keys/nano.json', 'utf8'));
const args = process.argv.slice(2);
const r = spawnSync('node', ['.scratch/pk-skill/scripts/no-node.js', ...args], {
  env: { ...process.env, NANO_SEED: k.seed },
  encoding: 'utf8', timeout: 120000,
});
console.log('exit', r.status);
console.log((r.stdout || '') + (r.stderr || ''));

// claim feeless402 starter faucet: challenge -> PoW -> POST
import { readFileSync } from 'node:fs';
import nc from 'nanocurrency';
const k = JSON.parse(readFileSync('wallet/keys/nano.json', 'utf8'));
const ch = await (await fetch('https://feeless402.com/faucet/challenge')).json();
console.log('challenge root', ch.root, 'difficulty', ch.difficulty);
const t0 = Date.now();
const work = await nc.computeWork(ch.root, { workThreshold: ch.difficulty });
console.log('work', work, 'in', Date.now() - t0, 'ms');
const r = await fetch('https://feeless402.com/faucet', {
  method: 'POST', headers: { 'content-type': 'application/json' },
  body: JSON.stringify({ address: k.address, work }),
});
console.log('claim ->', r.status, (await r.text()).slice(0, 400));

// claim faucet with GPU work from pursekeeper
import { readFileSync } from 'node:fs';
import nc from 'nanocurrency';
const k = JSON.parse(readFileSync('wallet/keys/nano.json', 'utf8'));
const ch = await (await fetch('https://feeless402.com/faucet/challenge')).json();
console.log('root', ch.root, 'difficulty', ch.difficulty);
const w0 = Date.now();
const wr = await (await fetch('https://pursekeeper.dev/v1/work', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ hash: ch.root }) })).json();
console.log('work svc ->', JSON.stringify(wr).slice(0, 200), Date.now() - w0, 'ms');
if (!wr.work) process.exit(1);
const ok = await nc.validateWork({ blockHash: ch.root, work: wr.work, threshold: ch.difficulty });
console.log('validates at faucet difficulty:', ok);
const r = await fetch('https://feeless402.com/faucet', {
  method: 'POST', headers: { 'content-type': 'application/json' },
  body: JSON.stringify({ address: k.address, work: wr.work }),
});
console.log('claim ->', r.status, (await r.text()).slice(0, 400));

// claim faucet with cookie binding
import { readFileSync } from 'node:fs';
import nc from 'nanocurrency';
const k = JSON.parse(readFileSync('wallet/keys/nano.json', 'utf8'));
const ch = await fetch('https://feeless402.com/faucet/challenge');
const cookie = ch.headers.getSetCookie ? ch.headers.getSetCookie() : [];
const jc = await ch.json();
console.log('root', jc.root, 'cookies', JSON.stringify(cookie).slice(0, 200));
const wr = await (await fetch('https://pursekeeper.dev/v1/work', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ hash: jc.root }) })).json();
console.log('work', wr.work, wr.threshold, wr.source);
const ok = await nc.validateWork({ blockHash: jc.root, work: wr.work, threshold: jc.difficulty });
console.log('validates:', ok);
const hdr = { 'content-type': 'application/json' };
for (const c of cookie) hdr['cookie'] = (hdr['cookie'] ? hdr['cookie'] + '; ' : '') + c.split(';')[0];
const r = await fetch('https://feeless402.com/faucet', { method: 'POST', headers: hdr, body: JSON.stringify({ address: k.address, work: wr.work }) });
console.log('claim ->', r.status, (await r.text()).slice(0, 500));

